import pandas as pd


def run(inputs):
    target_state = inputs["target_state"]
    cdc_events = inputs["cdc_events"]

    # Distinct by seq: at-least-once delivery de-duplication.
    events = cdc_events.drop_duplicates(subset="seq", keep="first")

    # Build target_state lookup.
    target = {}
    for row in target_state.itertuples(index=False):
        target[int(row.order_id)] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": int(row.last_seq),
        }

    # Group events by order_id.
    events_by_order = {}
    for row in events.itertuples(index=False):
        oid = int(row.order_id)
        events_by_order.setdefault(oid, []).append(
            (int(row.seq), row.op, row.status, row.amount)
        )

    all_order_ids = set(target.keys()) | set(events_by_order.keys())

    new_state_rows = []
    tombstone_rows = []

    for oid in all_order_ids:
        has_target = oid in target
        threshold = target[oid]["last_seq"] if has_target else None

        order_events = events_by_order.get(oid, [])
        if threshold is not None:
            filtered = [e for e in order_events if e[0] > threshold]
        else:
            filtered = list(order_events)

        filtered.sort(key=lambda e: e[0])

        # Initial state from target_state (if present).
        if has_target:
            exists = True
            status = target[oid]["status"]
            amount = target[oid]["amount"]
            last_seq = target[oid]["last_seq"]
        else:
            exists = False
            status = None
            amount = None
            last_seq = None

        had_row_ever = exists
        last_event = None  # (seq, op) of the last applied event

        for seq, op, ev_status, ev_amount in filtered:
            last_event = (seq, op)
            if op in ("I", "U"):
                if exists:
                    status = ev_status
                    if op == "U" and pd.isna(ev_amount):
                        # U with NULL amount leaves existing amount unchanged.
                        pass
                    else:
                        amount = ev_amount
                    last_seq = seq
                else:
                    status = ev_status
                    amount = ev_amount
                    last_seq = seq
                    exists = True
                had_row_ever = True
            elif op == "D":
                if exists:
                    exists = False
                    status = None
                    amount = None
                    last_seq = None
                # D on a missing order is a no-op.

        if exists:
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": status,
                    "amount": amount,
                    "last_seq": last_seq,
                }
            )
        else:
            if had_row_ever and last_event is not None and last_event[1] == "D":
                tombstone_rows.append(
                    {
                        "order_id": oid,
                        "deleted_seq": last_event[0],
                    }
                )

    if new_state_rows:
        new_state = pd.DataFrame(
            new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
        )
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
    else:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype="object"),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows, columns=["order_id", "deleted_seq"])
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state, "tombstones": tombstones}
